tests.code:
% name: Single temperatures
% points: 8
assert(abs(c2f(0) - 32) < 1e-9, 'c2f(0) should be 32 (water freezes)');
assert(abs(c2f(100) - 212) < 1e-9, 'c2f(100) should be 212 (water boils)');
assert(abs(c2f(-40) - (-40)) < 1e-9, 'c2f(-40) should be -40');
assert(abs(c2f(37) - 98.6) < 1e-9, 'c2f(37) should be 98.6');

% name: A row of temperatures
% points: 6
f = c2f([0 10 20 30]);
assert(isequal(size(f), [1 4]), 'The output must have the same size as the input');
assert(all(abs(f - [32 50 68 86]) < 1e-9), 'c2f([0 10 20 30]) should be [32 50 68 86]');

% name: Regular days
% points: 10
assert(isequal(ticket_price(2, false), 0), 'A 2-year-old gets in free');
assert(isequal(ticket_price(10, false), 6), 'A 10-year-old pays 6');
assert(isequal(ticket_price(30, false), 11), 'A 30-year-old pays 11');
assert(isequal(ticket_price(70, false), 8), 'A 70-year-old pays 8');

% name: Monday discount
% points: 8
assert(isequal(ticket_price(12, true), 4), 'On Monday a 12-year-old pays 6 - 2 = 4');
assert(isequal(ticket_price(40, true), 9), 'On Monday a 40-year-old pays 11 - 2 = 9');
assert(isequal(ticket_price(80, true), 6), 'On Monday an 80-year-old pays 8 - 2 = 6');
assert(isequal(ticket_price(3, true), 0), 'A free ticket stays free on Monday');

% name: Examples from the problem statement
% points: 10
assert(isequal(longest_streak([1 1 0 1 1 1 0]), 3), 'longest_streak([1 1 0 1 1 1 0]) should be 3');
assert(isequal(longest_streak([4 4 4 4]), 4), 'longest_streak([4 4 4 4]) should be 4');
assert(isequal(longest_streak([7 8 9]), 1), 'longest_streak([7 8 9]) should be 1');

% name: Empty vector and single value
% points: 5
assert(isequal(longest_streak([]), 0), 'An empty vector has no streak: the answer is 0');
assert(isequal(longest_streak(5), 1), 'A single value is a streak of length 1');

