% points: 8
total = rain_summary('rain_week.csv');
assert(abs(total - 24) < 1e-9, 'The total for rain_week.csv should be 24');

% name: Wettest day and dry days
% points: 10
[total, wettest_day, dry_days] = rain_summary('rain_week.csv');
assert(abs(total - 24) < 1e-9, 'The total for rain_week.csv should be 24');
